sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float level;
uniform float softness;
uniform float invert;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    half v = smoothstep(half(level - softness), half(level + softness) + 0.0001, luma(c.rgb));
    if (invert > 0.5) v = 1.0 - v;
    return half4(half3(v) * c.a, c.a);
}
